def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Locate repeated two-row stripe motifs.  A motif with a shared blank
    # suffix is a clipped copy when the same columns are occupied in another
    # motif; mark that continuation with 1.
    bg = max(range(10), key=lambda c: sum(v == c for row in grid for v in row))
    pairs = []
    r = 0
    while r < h - 1:
        if any(v != bg for v in grid[r]) and any(v != bg for v in grid[r+1]):
            pairs.append((r, r+1))
            r += 2
        else:
            r += 1
    for a, b in pairs:
        suffix = 0
        while suffix < w and grid[a][w-1-suffix] == bg and grid[b][w-1-suffix] == bg:
            suffix += 1
        if suffix >= 2 and any(grid[x][c] != bg for u,v in pairs if (u,v)!=(a,b) for x in (u,v) for c in range(w-suffix,w)):
            for c in range(w-suffix,w):
                out[a][c] = 1
                out[b][c] = 1
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(range(10), key=lambda c: sum(v == c for row in grid for v in row))
    prefix_tolerance = max(2, w // 4)

    for r, row in enumerate(grid):
        # Find the beginning of the trailing background run.
        k = w
        while k > 0 and row[k - 1] == bg:
            k -= 1
        if k == w or k == 0:
            continue
        fg = [v for v in row[:k] if v != bg]
        if not fg:
            continue
        color = max(set(fg), key=fg.count)

        # If another row repeats this motif and continues in the same color
        # across the trailing gap, mark the absent continuation as 1.
        for s, other in enumerate(grid):
            if s == r or not all(other[c] == color for c in range(k, w)):
                continue
            errors = sum(row[c] != other[c] for c in range(k))
            if errors <= prefix_tolerance:
                for c in range(k, w):
                    out[r][c] = 1
                break
    return out
